function smoothstep(x) {
  const c = clamp(x, 0, 1);
  return c * c * (3 - 2 * c);
}

function cubicBezier(p0, c1, c2, p3, t) {
  const u = 1 - t;
  const u2 = u * u;
  const t2 = t * t;
  return u2 * u * p0 + 3 * u2 * t * c1 + 3 * u * t2 * c2 + t2 * t * p3;
}

function docOffsetTop(el) {
  let top = 0;
  let cur = el;
  while (cur) {
    top += cur.offsetTop || 0;
    cur = cur.offsetParent;
  }
  return top;
}

function measureFlightMetrics() {
  if (smallScreen.matches) return;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const heroRect = hero.getBoundingClientRect();
  const aRect = (anchor || host).getBoundingClientRect();

  const startW = aRect.width || host.clientWidth;
  const startH = aRect.height || host.clientHeight;
  if (!startW || !startH) return;

  const sx = window.scrollX;
  const sy = window.scrollY;
  flight.startW = startW;
  flight.startH = startH;
  flight.startCX = aRect.left + sx + startW / 2;
  flight.startCY = aRect.top + sy + startH / 2;

  flight.heroCX = heroRect.left + sx + heroRect.width / 2;
  flight.heroCY = heroRect.top + sy + heroRect.height / 2;
  flight.heroRX = Math.max(heroRect.width * 0.55, 460);
  flight.heroRY = Math.max(heroRect.height * 0.5, 320);

  const endW = clamp(vw * 0.088, 114, 152);
  const endH = endW * (startH / startW);
  const endLeft = clamp(vw * 0.018, 16, 32);
  const hudH = hud ? hud.getBoundingClientRect().height : 34;
  const endBottom = hudH + 14;

  flight.endScale = endW / startW;
  flight.endCX = endLeft + endW / 2;
  flight.endCY = Math.max(endH / 2 + 96, vh - endBottom - endH / 2);

  if (connectCard) {
    const cRect = connectCard.getBoundingClientRect();
    const perchW = clamp(vw * 0.125, 146, 196);
    const perchH = perchW * (startH / startW);
    const insetRight = clamp(vw * 0.018, 18, 34);
    flight.contactDocTop = docOffsetTop(connectCard);
    flight.contactCX = cRect.right + sx - insetRight - perchW / 2;
    flight.contactScale = perchW / startW;
    flight.contactPerchH = perchH;
    flight.contactOffsetY = -perchH * 0.42;
  } else {
    flight.contactPerchH = 0;
  }

  expFlight.perchW = endW;
  expFlight.perchH = endH;
  expFlight.scale = flight.endScale;
  flight.headerBottom = siteHeader ? siteHeader.getBoundingClientRect().bottom : 81;

  const maxScroll = Math.max(0, document.documentElement.scrollHeight - vh);
  const baseDist = clamp(heroRect.height * 0.78, 420, 620);
  flight.flightDist = maxScroll > 0 ? Math.min(baseDist, Math.max(240, maxScroll * 0.5)) : baseDist;
  flight.dirtyMetrics = true;
}

function computeScrollProgress() {
  if (!flight.flightDist) return 0;
  return clamp(window.scrollY / flight.flightDist, 0, 1);
}

function computeWorkCorridorMetrics(state) {
  if (!state || !state.valid || !state.headEl || !flight.startW || !flight.startH) {
    return { valid: false };
  }
  const headRect = state.headEl.getBoundingClientRect();
  if (!headRect.width || !headRect.height) return { valid: false };

  const gapW = state.noteOffsetLeft - state.titleOffsetRight;
  if (gapW < 155 || state.headHeight < 78) return { valid: false };

  const perchW = clamp(Math.min(gapW * 0.34, state.headHeight * 0.84), 88, 126);
  const perchH = perchW * (flight.startH / flight.startW);
  const scale = perchW / flight.startW;

  const visHalfW = perchW * 0.45;
  const padX = clamp(gapW * 0.06, 12, 22);
  const minX = headRect.left + state.titleOffsetRight + visHalfW + padX;
  const maxX = headRect.left + state.noteOffsetLeft - visHalfW - padX;
  if (maxX - minX < 36) return { valid: false };

  const rawMidY = headRect.top + (state.corridorTopOffset + state.corridorBottomOffset) * 0.5;
  const minHeaderClearY = (flight.headerBottom || 81) + 4 + perchH * 0.46;
  const cy = Math.max(minHeaderClearY, rawMidY - 2);

  return { valid: true, minX, maxX, cy, scale, perchW, perchH, headTop: headRect.top };
}

function computeWorkTarget() {
  const state = registry.workMascotState;
  if (
    !state ||
    !state.active ||
    !state.engaged ||
    state.bypassed ||
    !state.valid ||
    registry.suppressWorkMascot
  ) {
    return 0;
  }
  if (computeScrollProgress() < 0.72) return 0;
  const m = computeWorkCorridorMetrics(state);
  if (!m.valid) return 0;

  const topDelta = m.headTop - state.stickyTop;
  const bottomExitT = smoothstep((topDelta + 118) / 110);
  const topExitT = smoothstep((72 - topDelta) / 72);
  return bottomExitT * topExitT;
}

function getExpAnchorPos(state, idx, vpTop, hudBottom) {
  const a = state.anchors && state.anchors[idx];
  if (!a) {
    return { x: state.viewportW * 0.25, y: hudBottom + expFlight.perchH * 0.5 + 8 };
  }
  const x = a.stageX + state.currentX;
  const minY = hudBottom + expFlight.perchH * 0.4 + 2;
  const rawY = vpTop + a.localY - expFlight.perchH * 0.415 - 6;
  return { x, y: Math.max(minY, rawY) };
}

function computeExpTarget() {
  const state = registry.expMascotState;
  if (!state || !state.active || !state.section || !state.viewport) return 0;
  if (computeScrollProgress() < 0.85) return 0;
  const vh = window.innerHeight;
  const secTop = state.section.getBoundingClientRect().top;
  const vpTop = state.viewport.getBoundingClientRect().top;

  const enterStart = vh * 0.72;
  const enterEnd = state.stickyTop + vh * 0.1;
  const enterT = smoothstep((enterStart - secTop) / Math.max(enterStart - enterEnd, 100));

  const exitStart = state.stickyTop - 16;
  const exitEnd = state.stickyTop - 210;
  const exitT = smoothstep((vpTop - exitEnd) / Math.max(exitStart - exitEnd, 100));

  return enterT * exitT;
}

function getExpRightLimit(vpW) {
  return Math.min(vpW - Math.max(122, expFlight.perchW * 0.98), vpW * 0.91);
}

function getExpForwardTrigger(anchors, idx, vpW) {
  const a = anchors[idx];
  const nextA = anchors[idx + 1];
  const baseLeftDisp = Math.min(92, Math.max(36, a.restX - a.width / 2 - 18));
  if (!nextA) return baseLeftDisp;
  const fwdMaxNextX = getExpRightLimit(vpW) - 58;
  const enterOnScreenDisp = nextA.stageX - a.stageX + a.restX - fwdMaxNextX;
  return Math.max(baseLeftDisp, enterOnScreenDisp);
}

function resolveExpPanelTarget(snap = false) {
  const state = registry.expMascotState;
  if (!state || !state.active || !state.anchors || !state.anchors.length) return;
  const anchors = state.anchors;
  const rightLimit = getExpRightLimit(state.viewportW);

  let next = clamp(expPerch.panel, 0, anchors.length - 1);
  while (next < anchors.length - 1) {
    const a = anchors[next];
    const dispLeft = a.restX - (a.stageX + state.currentX);
    const fwdTrigger = getExpForwardTrigger(anchors, next, state.viewportW);
    if (dispLeft >= fwdTrigger) next++;
    else break;
  }
  while (next > 0) {
    const currCenter = anchors[next].stageX + state.currentX;
    const prevA = anchors[next - 1];
    const dispLeftPrev = prevA.restX - (prevA.stageX + state.currentX);
    const prevFwd = getExpForwardTrigger(anchors, next - 1, state.viewportW);
    const backDispThreshold = Math.max(8, prevFwd - 58);
    if (currCenter >= rightLimit || dispLeftPrev <= backDispThreshold) next--;
    else break;
  }

  if (snap || expFlight.p < 0.04) {
    const changed = next !== expPerch.panel;
    expPerch.panel = next;
    expPerch.fromPanel = next;
    expPerch.toPanel = next;
    expPerch.hopT = 1;
    expPerch.useSnap = false;
    if (changed) registry.onExpPerchChange?.(next);
    return;
  }

  if (next !== expPerch.panel) {
    const prev = expPerch.panel;
    expPerch.hopDir = next > prev ? 1 : -1;
    if (expPerch.hopT < 1 && expPerch.hasLive) {
      expPerch.useSnap = true;
      expPerch.snapX = expPerch.liveX;
      expPerch.snapY = expPerch.liveY;
    } else {
      expPerch.useSnap = false;
      expPerch.fromPanel = prev;
    }
    expPerch.toPanel = next;
    expPerch.panel = next;
    expPerch.hopT = 0;
    expPerch.hopDur = Math.abs(next - prev) > 1 ? 0.54 : 0.46;
    registry.onExpPerchChange?.(next);
    if (!running && !motionOff() && !document.hidden) start();
  }
}

function computeExpLivePos() {
  const state = registry.expMascotState;
  if (!state || !state.active || !state.viewport) {
    return { x: flight.endCX, y: flight.endCY };
  }
  const vpTop = state.viewport.getBoundingClientRect().top;
  const hudBottom = state.hudEl ? state.hudEl.getBoundingClientRect().bottom : vpTop + 41;
  const minY = hudBottom + expFlight.perchH * 0.42 + 4;

  if (expPerch.hopT >= 1) {
    const pos = getExpAnchorPos(state, expPerch.panel, vpTop, hudBottom);
    expPerch.liveX = pos.x;
    expPerch.liveY = pos.y;
    expPerch.hasLive = true;
    return pos;
  }

  const tH = clamp(expPerch.hopT, 0, 1);
  const u = tH < 0.5 ? 4 * tH * tH * tH : 1 - Math.pow(-2 * tH + 2, 3) / 2;
  const toPos = getExpAnchorPos(state, expPerch.toPanel, vpTop, hudBottom);
  const fromPos = expPerch.useSnap
    ? { x: expPerch.snapX, y: expPerch.snapY }
    : getExpAnchorPos(state, expPerch.fromPanel, vpTop, hudBottom);

  const rawX = fromPos.x + (toPos.x - fromPos.x) * u;
  const rawY = fromPos.y + (toPos.y - fromPos.y) * u;
  const hopSin = Math.sin(Math.PI * tH);
  const desiredArc = clamp(Math.abs(toPos.x - fromPos.x) * 0.075, 28, 52);
  const maxHeadroom = Math.max(10, rawY - minY);
  const hopLift = hopSin * Math.min(desiredArc, maxHeadroom);

  const x = rawX;
  const y = rawY - hopLift;
  expPerch.liveX = x;
  expPerch.liveY = y;
  expPerch.hasLive = true;
  return { x, y };
}

function computeContactTarget() {
  if (!connectCard || !flight.contactPerchH) return 0;
  if (computeScrollProgress() < 0.95) return 0;
  const vh = window.innerHeight;
  const cardTop = flight.contactDocTop - window.scrollY;
  const enterStart = vh * 0.9;
  const enterEnd = vh * 0.6;
  const enterT = smoothstep((enterStart - cardTop) / Math.max(enterStart - enterEnd, 120));

  const exitStart = Math.max(245, 114 + flight.contactPerchH * 0.92);
  const exitEnd = Math.max(105, exitStart - 135);
  const exitT = smoothstep((cardTop - exitEnd) / Math.max(exitStart - exitEnd, 80));

  return enterT * exitT;
}

function applyFlightTransform(force = false) {
  if (!flight.active) return;

  const p = clamp(flight.p, 0, 1);
  const t = 0.5 - 0.5 * Math.cos(Math.PI * p);

  const p0x = flight.startCX - window.scrollX;
  const p0y = flight.startCY;
  const p3x = flight.endCX;
  const p3y = flight.endCY + scrollState.buoyY;
  const dx = p3x - p0x;
  const dy = p3y - p0y;

  const dockX = cubicBezier(p0x, p0x + dx * 0.16, p0x + dx * 0.78, p3x, t);
  const dockY = cubicBezier(p0y, p0y + dy * 0.42, p0y + dy * 0.96, p3y, t);
  const dockEase = smoothstep(p);
  const dockS = 1 + (flight.endScale - 1) * dockEase;

  let cx = dockX;
  let cy = dockY;
  let s = dockS;
  let dock = dockEase;

  const wp = clamp(workFlight.p, 0, 1);
  const workState = registry.workMascotState;
  const workMetrics = wp > 0.0005 ? computeWorkCorridorMetrics(workState) : null;
  if (wp > 0.0005 && workMetrics && workMetrics.valid) {
    const workEase = smoothstep(wp);
    const tW = 0.5 - 0.5 * Math.cos(Math.PI * wp);
    const posP = clamp(workFlight.posP, 0, 1);
    const targetX = workMetrics.minX + (workMetrics.maxX - workMetrics.minX) * posP;
    const targetY = workMetrics.cy;
    workFlight.scale = workMetrics.scale;
    workFlight.perchW = workMetrics.perchW;
    workFlight.perchH = workMetrics.perchH;

    if (workEase >= 0.999) {
      cx = targetX;
      cy = targetY;
      s = workMetrics.scale;
      dock = 0;
    } else {
      const wdx = targetX - dockX;
      const wdy = targetY - dockY;
      const wc1x = dockX + wdx * 0.52;
      const wc1y = dockY + wdy * 0.14;
      const wc2x = dockX + wdx * 0.88;
      const wc2y = targetY - wdy * 0.24;
      cx = cubicBezier(dockX, wc1x, wc2x, targetX, tW);
      cy = cubicBezier(dockY, wc1y, wc2y, targetY, tW);
      s = dockS + (workMetrics.scale - dockS) * workEase;
      dock = dockEase * (1 - workEase);
    }
  }

  const ep = clamp(expFlight.p, 0, 1);
  if (ep > 0.0005 && registry.expMascotState && registry.expMascotState.active) {
    const expEase = smoothstep(ep);
    const expPos = computeExpLivePos();
    if (expEase >= 0.999) {
      cx = expPos.x;
      cy = expPos.y;
      s = expFlight.scale;
      dock = 0;
    } else {
      const tE = 0.5 - 0.5 * Math.cos(Math.PI * ep);
      const liftE = Math.sin(Math.PI * ep) * 26;
      cx = dockX + (expPos.x - dockX) * tE;
      cy = dockY + (expPos.y - dockY) * tE - liftE;
      s = dockS + (expFlight.scale - dockS) * expEase;
      dock = dockEase * (1 - expEase);
    }
  }

  const cp = clamp(contactFlight.p, 0, 1);
  if (cp > 0.0005 && flight.contactPerchH > 0) {
    const contactEase = smoothstep(cp);
    const tC = 0.5 - 0.5 * Math.cos(Math.PI * cp);
    const perchX = flight.contactCX - window.scrollX;
    /* Keep the perch anchor below the fixed header so scrolling fast from
       #contact into .site-footer glides down-left instead of arching up into .site-header. */
    const minPerchY = Math.max(114 + flight.contactPerchH * 0.5, 195);
    const rawPerchY = flight.contactDocTop - window.scrollY + flight.contactOffsetY;
    const perchY = Math.max(minPerchY, rawPerchY);
    const cdx = perchX - dockX;
    const cdy = perchY - dockY;

    const c1x = dockX + cdx * 0.28;
    const c1y = Math.max(dockY, perchY) - Math.abs(cdy) * 0.15;
    const c2x = dockX + cdx * 0.78;
    const c2y = Math.max(minPerchY - 12, perchY - 26);

    cx = cubicBezier(dockX, c1x, c2x, perchX, tC);
    cy = cubicBezier(dockY, c1y, c2y, perchY, tC);
    s = dockS + (flight.contactScale - dockS) * contactEase;
    dock = dockEase * (1 - contactEase);
  }

  flight.liveCX = cx;
  flight.liveCY = cy;

  const tx = cx - flight.startW / 2;
  const ty = cy - flight.startH / 2;
  if (
    force ||
    flight.dirtyMetrics ||
    Math.abs(tx - flight.lastTx) >= 0.01 ||
    Math.abs(ty - flight.lastTy) >= 0.01 ||
    Math.abs(s - flight.lastS) >= 0.0001 ||
    Math.abs(dock - flight.lastDock) >= 0.0001
  ) {
    flight.dirtyMetrics = false;
    flight.lastTx = tx;
    flight.lastTy = ty;
    flight.lastS = s;
    flight.lastDock = dock;
    host.style.transform = `translate3d(${tx.toFixed(2)}px, ${ty.toFixed(2)}px, 0)`;
    host.style.setProperty("--mascot-scale", s.toFixed(4));
    host.style.setProperty("--mascot-dock", dock.toFixed(4));
    if (rigEl) {
      rigEl.style.transform = `scale(${s.toFixed(4)})`;
    }
  }

  const isFloating = p > 0.03 || flight.targetP > 0.03;
  if (isFloating !== flight.floatingClass) {
    flight.floatingClass = isFloating;
    host.classList.toggle("is-floating", isFloating);
  }

  const isExpPerched = ep > 0.65 && Boolean(registry.expMascotState && registry.expMascotState.active);
  if (isExpPerched !== expFlight.perchClass) {
    expFlight.perchClass = isExpPerched;
    host.classList.toggle("mascot--exp-perched", isExpPerched);
    registry.onExpPerchActive?.(isExpPerched, expPerch.panel);
  }

  const isExpHopping = isExpPerched && expPerch.hopT < 0.96;
  if (isExpHopping !== expPerch.hoppingClass) {
    expPerch.hoppingClass = isExpHopping;
    host.classList.toggle("mascot--exp-hopping", isExpHopping);
  }

  const vpW = (registry.expMascotState && registry.expMascotState.viewportW) || window.innerWidth;
  const speechOnX = vpW - 295;
  const speechOffX = vpW - 435;
  const wantSpeechLeft = isExpPerched && (expPerch.speechLeftClass ? cx > speechOffX : cx > speechOnX);
  if (wantSpeechLeft !== expPerch.speechLeftClass) {
    expPerch.speechLeftClass = wantSpeechLeft;
    host.classList.toggle("mascot--exp-speech-left", wantSpeechLeft);
  }

  const isWorkPerched =
    wp > 0.55 &&
    Boolean(
      workMetrics &&
        workMetrics.valid &&
        workState &&
        workState.active &&
        workState.engaged &&
        !workState.bypassed
    );
  if (isWorkPerched !== workFlight.perchClass) {
    workFlight.perchClass = isWorkPerched;
    host.classList.toggle("mascot--work-perched", isWorkPerched);
  }

  const wantWorkSpeechLeft =
    isWorkPerched &&
    (workFlight.speechLeftClass ? workFlight.posP >= 0.36 : workFlight.posP >= 0.52);
  if (wantWorkSpeechLeft !== workFlight.speechLeftClass) {
    workFlight.speechLeftClass = wantWorkSpeechLeft;
    host.classList.toggle("mascot--work-speech-left", wantWorkSpeechLeft);
  }
}

function syncFlightMode(snapToScroll = false) {
  const shouldFloat = canFloat();
  if (shouldFloat && !flight.active) {
    flight.active = true;
    host.classList.add("mascot--flight");
    measureFlightMetrics();
    flight.targetP = computeScrollProgress();
    workFlight.targetP = computeWorkTarget();
    workFlight.targetPosP = clamp(registry.workMascotState?.progress ?? 0, 0, 1);
    expFlight.targetP = computeExpTarget();
    contactFlight.targetP = computeContactTarget();
    if (snapToScroll) {
      flight.p = flight.targetP;
      flight.vel = 0;
      flight.bank = 0;
      workFlight.p = workFlight.targetP;
      workFlight.vel = 0;
      workFlight.posP = workFlight.targetPosP;
      workFlight.posVel = 0;
      expFlight.p = expFlight.targetP;
      expFlight.vel = 0;
      resolveExpPanelTarget(true);
      contactFlight.p = contactFlight.targetP;
      contactFlight.vel = 0;
    } else {
      if (workFlight.targetP > 0 && workFlight.p <= 0.002) {
        workFlight.posP = workFlight.targetPosP;
      }
      resolveExpPanelTarget(false);
    }
    applyFlightTransform(true);
  } else if (!shouldFloat && flight.active) {
    flight.active = false;
    flight.floatingClass = false;
    flight.p = 0;
    flight.targetP = 0;
    flight.vel = 0;
    flight.bank = 0;
    flight.lastTx = NaN;
    flight.lastTy = NaN;
    flight.lastS = NaN;
    flight.lastDock = NaN;
    workFlight.p = 0;
    workFlight.targetP = 0;
    workFlight.vel = 0;
    workFlight.posP = 0;
    workFlight.targetPosP = 0;
    workFlight.posVel = 0;
    workFlight.perchClass = false;
    workFlight.speechLeftClass = false;
    expFlight.p = 0;
    expFlight.targetP = 0;
    expFlight.vel = 0;
    expFlight.perchClass = false;
    expPerch.panel = 0;
    expPerch.fromPanel = 0;
    expPerch.toPanel = 0;
    expPerch.hopT = 1;
    expPerch.useSnap = false;
    expPerch.hoppingClass = false;
    expPerch.speechLeftClass = false;
    expPerch.landBounceT = -1;
    expPerch.hasLive = false;
    host.classList.remove("mascot--exp-speech-left", "mascot--work-perched", "mascot--work-speech-left");
    contactFlight.p = 0;
    contactFlight.targetP = 0;
    contactFlight.vel = 0;
    scrollState.vel = 0;
    scrollState.targetVel = 0;
    scrollState.buoyY = 0;
    host.classList.remove("mascot--flight", "is-floating", "mascot--exp-perched", "mascot--exp-hopping");
    host.style.transform = "";
    host.style.removeProperty("--mascot-scale");
    host.style.removeProperty("--mascot-dock");
    if (rigEl) {
      rigEl.style.transform = "";
    }
    robot.rotation.set(0, 0, 0);
  }
}

/* ------------------------------------------------------------------ */
/* Pointer — measured against the hero, not the 262px box, or the      */
/* clamp saturates before the cursor has crossed a third of the page.  */
/* ------------------------------------------------------------------ */

const lastPointer = { x: 0, y: 0, has: false };

function pointerToTarget(clientX, clientY, out) {
  if (flight.active) {
    const dockEase = Math.max(
      smoothstep(flight.p),
      smoothstep(workFlight.p),
      smoothstep(contactFlight.p),
      smoothstep(expFlight.p)
    );
    const heroRefX = flight.heroCX - window.scrollX;
    const heroRefY = flight.heroCY - window.scrollY;
    const refX = heroRefX + (flight.liveCX - heroRefX) * dockEase;
    const refY = heroRefY + (flight.liveCY - heroRefY) * dockEase;
    const rx = flight.heroRX + (Math.max(window.innerWidth * 0.72, 560) - flight.heroRX) * dockEase;
    const ry = flight.heroRY + (Math.max(window.innerHeight * 0.72, 420) - flight.heroRY) * dockEase;
    out.x = clamp((clientX - refX) / rx, -1.2, 1.2);
    out.y = clamp((clientY - refY) / ry, -1.2, 1.2);
    return true;
  }
  const rect = hero.getBoundingClientRect();
  if (!rect.width || !rect.height) return false;
  const rx = Math.max(rect.width * 0.55, 460);
  const ry = Math.max(rect.height * 0.5, 320);
  out.x = clamp((clientX - (rect.left + rect.width / 2)) / rx, -1.2, 1.2);
  out.y = clamp((clientY - (rect.top + rect.height / 2)) / ry, -1.2, 1.2);
  return true;
}

function onPointer(event) {
  if (event.clientX === undefined) return;
  if (event.pointerType === "touch" || window.innerWidth <= 768 || window.matchMedia("(pointer: coarse)").matches) {
    return;
  }
  lastPointer.x = event.clientX;
  lastPointer.y = event.clientY;
  lastPointer.has = true;
  pointerToTarget(event.clientX, event.clientY, target);
  lastMoveT = elapsed;
  glance.until = -1;
}

window.addEventListener("pointermove", onPointer, { passive: true });
window.addEventListener("pointerdown", onPointer, { passive: true });

/* ------------------------------------------------------------------ */
/* Model prep                                                          */
/* ------------------------------------------------------------------ */

function prepareModel(object, opts) {
  const { glossy = false, rim = null, tint = "#ffffff" } = opts;
  const meshes = [];
  object.traverse((o) => {
    if (o.isMesh) meshes.push(o);
  });
  for (const mesh of meshes) {
    const params = { color: tint };
    if (glossy) {
      Object.assign(params, {
        metalness: 0.1,
        roughness: 0.3,
        clearcoat: 1.0,
        clearcoatRoughness: 0.16,
        envMapIntensity: 0.9,
      });
    } else {
      Object.assign(params, {
        metalness: 0,
        roughness: 0.48,
        clearcoat: 0.3,
        clearcoatRoughness: 0.4,
        envMapIntensity: 0.55,
      });
    }
    mesh.material = new THREE.MeshPhysicalMaterial(params);
    if (rim) addRimShell(mesh, rim.color, rim.power, rim.strength);
  }
}

function normaliseHead(object) {
  object.updateMatrixWorld(true);
  let box = new THREE.Box3().setFromObject(object);
  const size = box.getSize(new THREE.Vector3());
  object.scale.multiplyScalar(2 / size.z);
  object.updateMatrixWorld(true);
  box = new THREE.Box3().setFromObject(object);
  const centre = box.getCenter(new THREE.Vector3());
  object.position.set(-centre.x, -(box.min.y + 1), -centre.z);
  object.updateMatrixWorld(true);
}

/* ------------------------------------------------------------------ */
/* Visor                                                               */
/* ------------------------------------------------------------------ */

function roundedRectShape(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(-x - r, y);
  s.quadraticCurveTo(-x, y, -x, y + r);
  s.lineTo(-x, -y - r);
  s.quadraticCurveTo(-x, -y, -x - r, -y);
  s.lineTo(x + r, -y);
  s.quadraticCurveTo(x, -y, x, -y - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function subdivide4(geo) {
  const pos = geo.attributes.position;
  const verts = [];
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  for (let i = 0; i < pos.count; i += 3) {
    a.fromBufferAttribute(pos, i);
    b.fromBufferAttribute(pos, i + 1);
    c.fromBufferAttribute(pos, i + 2);
    const ab = a.clone().add(b).multiplyScalar(0.5);
    const bc = b.clone().add(c).multiplyScalar(0.5);
    const ca = c.clone().add(a).multiplyScalar(0.5);
    verts.push(
      a.x, a.y, a.z, ab.x, ab.y, ab.z, ca.x, ca.y, ca.z,
      ab.x, ab.y, ab.z, b.x, b.y, b.z, bc.x, bc.y, bc.z,
      ca.x, ca.y, ca.z, bc.x, bc.y, bc.z, c.x, c.y, c.z,
      ab.x, ab.y, ab.z, bc.x, bc.y, bc.z, ca.x, ca.y, ca.z
    );
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  return g;
}

function visorGeometry(w, h, corner, centerY, radius) {
  let g = new THREE.ShapeGeometry(roundedRectShape(w, h, corner), 48).toNonIndexed();
  for (let i = 0; i < 3; i++) g = subdivide4(g);
  const p = g.attributes.position;
  const normals = new Float32Array(p.count * 3);
  const v = new THREE.Vector3();
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i) + centerY;
    const z = Math.sqrt(Math.max(radius * radius - x * x - y * y, 0));
    p.setXYZ(i, x, y, z);
    v.set(x, y, z).normalize();
    normals[i * 3] = v.x;
    normals[i * 3 + 1] = v.y;
    normals[i * 3 + 2] = v.z;
  }
  g.setAttribute("normal", new THREE.BufferAttribute(normals, 3));
  g.computeBoundingSphere();
  return g;
}

function addVisor(R) {
  const bezel = new THREE.Mesh(
    visorGeometry(1.86, 1.12, 0.46, -0.07, R * 1.03),
    new THREE.MeshPhysicalMaterial({
      color: C.bezel,
      roughness: 0.3,
      metalness: 0.3,
      clearcoat: 0.8,
      polygonOffset: true,
      polygonOffsetFactor: -6,
      polygonOffsetUnits: -6,
    })
  );
  bezel.renderOrder = 3;

  const glass = new THREE.Mesh(
    visorGeometry(1.74, 1.0, 0.4, -0.07, R * 1.036),
    new THREE.MeshPhysicalMaterial({
      color: 0x000000,
      roughness: 0.12,
      metalness: 0,
      clearcoat: 1,
      clearcoatRoughness: 0.1,
      envMapIntensity: 0.9,
      polygonOffset: true,
      polygonOffsetFactor: -8,
      polygonOffsetUnits: -8,
    })
  );
  glass.renderOrder = 4;

  head.add(bezel, glass);
}

/* ------------------------------------------------------------------ */
/* Eyes                                                                */
/* ------------------------------------------------------------------ */

const irisTex = radialTexture([
  [0, "#ffe6cd"],
  [0.45, "#e0a678"],
  [0.8, "#b9743f"],
  [1, "#8a5227"],
]);

function buildEye(side, R) {
  const x = 0.43 * side;
  const y = -0.08;
  const r = R * 1.055;
  const z = Math.sqrt(Math.max(r * r - x * x - y * y, 0));
  const g = new THREE.Group();
  g.position.set(x, y, z);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), g.position.clone().normalize());

  const eyeMat = (extra) =>
    new THREE.MeshBasicMaterial(
      Object.assign({ transparent: true, toneMapped: false, depthWrite: false, depthTest: false }, extra)
    );

  const halo = new THREE.Mesh(
    new THREE.CircleGeometry(0.42),
    eyeMat({ map: glowTex, color: C.copper, opacity: 0.34, blending: THREE.AdditiveBlending })
  );
  halo.position.z = -0.004;
  halo.renderOrder = 9;

  const ring = new THREE.Mesh(
    new THREE.RingGeometry(0.168, 0.212, 64),
    eyeMat({ color: new THREE.Color(1.35, 1.05, 0.82) })
  );
  ring.renderOrder = 10;

  const iris = new THREE.Mesh(
    new THREE.CircleGeometry(0.17),
    eyeMat({ map: irisTex, color: new THREE.Color(1.15, 1.0, 0.88) })
  );
  iris.position.z = 0.001;
  iris.renderOrder = 11;

  const pupilWrap = new THREE.Group();
  const pupil = new THREE.Mesh(new THREE.CircleGeometry(0.083), eyeMat({ color: C.pupil }));
  pupil.position.z = 0.003;
  pupil.renderOrder = 12;
  const glint = new THREE.Mesh(new THREE.CircleGeometry(0.022), eyeMat({ color: 0xfff4e8 }));
  glint.position.set(0.032, 0.034, 0.005);
  glint.renderOrder = 13;
  pupilWrap.add(pupil, glint);

  g.add(halo, ring, iris, pupilWrap);
  head.add(g);
  /* Every part is transparent with depth testing off, so the only thing
     standing between "pupil on iris" and "iris on pupil" is draw order.
     Distinct renderOrders make the stack deterministic; equal ones left
     it to a depth tie that flipped as the head turned. */
  return { group: g, pupilWrap, qSurface: g.quaternion.clone() };
}

/* ------------------------------------------------------------------ */
/* Antenna tips                                                        */
/* ------------------------------------------------------------------ */

function addAntennaBalls(meshes) {
  const sides = { left: [], right: [] };
  const v = new THREE.Vector3();
  for (const mesh of meshes) {
    const pos = mesh.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i).applyMatrix4(mesh.matrixWorld);
      if (v.y > 0.75 && Math.abs(v.x) > 0.15) (v.x < 0 ? sides.left : sides.right).push(v.clone());
    }
  }
  for (const key of ["left", "right"]) {
    const pts = sides[key];
    if (!pts.length) continue;
    let top = pts[0];
    for (const p of pts) if (p.y > top.y) top = p;
    const near = pts.filter((p) => p.distanceTo(top) <= 0.2 && p.y >= top.y - 0.1);
    const c = near.reduce((acc, p) => acc.add(p), new THREE.Vector3()).divideScalar(Math.max(near.length, 1));
    c.y = Math.max(c.y, top.y - 0.1);

    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(0.118, 32, 16),
      new THREE.MeshPhysicalMaterial({
        color: C.mint,
        emissive: C.mintGlow,
        emissiveIntensity: 1.6,
        roughness: 0.22,
        clearcoat: 1,
        clearcoatRoughness: 0.14,
      })
    );
    ball.position.copy(c);
    head.add(ball);

    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: glowTex,
        color: C.mint,
        opacity: 0.85,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
        depthWrite: false,
        transparent: true,
      })
    );
    glow.scale.set(0.62, 0.62, 1);
    glow.position.copy(c);
    head.add(glow);
    antennaGlows.push(glow);
  }
}

function mountHead(headRoot, detectAntennas) {
  head.add(headRoot);
  head.updateMatrixWorld(true);

  const meshes = [];
  headRoot.traverse((o) => {
    if (o.isMesh && !o.userData.rimShell) meshes.push(o);
  });

  const ray = new THREE.Raycaster(new THREE.Vector3(0, 0, 5), new THREE.Vector3(0, 0, -1));
  const hits = ray.intersectObjects(meshes, false);
  let R = 1;
  if (hits.length) R = clamp(hits[0].point.length(), 0.85, 1.1);

  /* Snap the normals of vertices that sit on the sphere to true radial,
     otherwise the clearcoat reflection breaks up across panel seams.
     Convert quantized integer normals (from meshopt compression) to float32 first. */
  const v = new THREE.Vector3();
  const n = new THREE.Vector3();
  for (const mesh of meshes) {
    const pos = mesh.geometry.attributes.position;
    let nor = mesh.geometry.attributes.normal;
    if (!nor) continue;
    if (!(nor.array instanceof Float32Array)) {
      const floatNormals = new Float32Array(nor.count * 3);
      for (let i = 0; i < nor.count; i++) {
        floatNormals[i * 3] = nor.getX(i);
        floatNormals[i * 3 + 1] = nor.getY(i);
        floatNormals[i * 3 + 2] = nor.getZ(i);
      }
      nor = new THREE.Float32BufferAttribute(floatNormals, 3);
      mesh.geometry.setAttribute("normal", nor);
    }
    const nInv = new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld).invert();
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i).applyMatrix4(mesh.matrixWorld);
      const d = v.length();
      if (Math.abs(d - R) <= R * 0.07) {
        n.copy(v).normalize().applyMatrix3(nInv).normalize();
        nor.setXYZ(i, n.x, n.y, n.z);
      }
    }
    nor.needsUpdate = true;
  }

  addVisor(R);
  eyes.push(buildEye(-1, R), buildEye(1, R));
  if (detectAntennas) addAntennaBalls(meshes);
}

/* ------------------------------------------------------------------ */
/* Arms                                                                */
/* ------------------------------------------------------------------ */

const ARM_REST = [
  { x: -1.32, y: -0.72, z: 0.15, rz: -0.62, phase: 0 },
  { x: 1.32, y: -0.72, z: 0.15, rz: 0.62, phase: Math.PI * 0.85 },
];

function normaliseArm(object) {
  object.updateMatrixWorld(true);
  let box = new THREE.Box3().setFromObject(object);
  const size = box.getSize(new THREE.Vector3());
  object.scale.multiplyScalar(0.78 / size.y);
  object.updateMatrixWorld(true);
  box = new THREE.Box3().setFromObject(object);
  const c = box.getCenter(new THREE.Vector3());
  object.position.set(-c.x, -c.y, -c.z);
  const wrap = new THREE.Group();
  wrap.add(object);
  return wrap;
}

function mountArms(armTpl) {
  const copies = [armTpl, armTpl.clone(true)];
  copies.forEach((object, i) => {
    const wrap = normaliseArm(object);
    const def = ARM_REST[i];
    wrap.position.set(def.x, def.y, def.z);
    wrap.rotation.z = def.rz;
    body.add(wrap);
    arms.push({ wrap, def });
  });
}

/* ------------------------------------------------------------------ */
/* Procedural fallbacks — used only if a GLB fails to arrive           */
/* ------------------------------------------------------------------ */

function buildFallbackHead() {
  const g = new THREE.Group();
  const mat = new THREE.MeshPhysicalMaterial({ color: 0x332c24, roughness: 0.26, clearcoat: 1 });
  g.add(new THREE.Mesh(new THREE.SphereGeometry(1, 64, 32), mat));
  for (const s of [-1, 1]) {
    const ear = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.2, 32), mat);
    ear.rotation.z = Math.PI / 2;
    ear.position.x = s * 1.0;
    g.add(ear);
  }
  for (const s of [-1, 1]) {
    const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.55, 16), mat);
    rod.position.set(s * 0.42, 1.25, 0);
    g.add(rod);
    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(0.09, 24, 12),
      new THREE.MeshPhysicalMaterial({
        color: C.mint,
        emissive: C.mintGlow,
        emissiveIntensity: 1.6,
        roughness: 0.22,
        clearcoat: 1,
        clearcoatRoughness: 0.14,
      })
    );
    ball.position.set(s * 0.42, 1.55, 0);
    g.add(ball);
    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: glowTex,
        color: C.mint,
        opacity: 0.85,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
        depthWrite: false,
        transparent: true,
      })
    );
    glow.scale.set(0.62, 0.62, 1);
    glow.position.copy(ball.position);
    g.add(glow);
    antennaGlows.push(glow);
  }
  const meshes = [];
  g.traverse((o) => {
    if (o.isMesh) meshes.push(o);
  });
  for (const m of meshes) addRimShell(m, C.copper, 4.5, 0.32);
  return g;
}

function buildFallbackArm() {
  const mat = new THREE.MeshPhysicalMaterial({
    color: C.shellDark,
    metalness: 0,
    roughness: 0.48,
    clearcoat: 0.3,
    clearcoatRoughness: 0.4,
    envMapIntensity: 0.55,
  });
  const mesh = new THREE.Mesh(new THREE.CapsuleGeometry(0.22, 0.42, 12, 32), mat);
  const g = new THREE.Group();
  g.add(mesh);
  addRimShell(mesh, C.copper, 2.6, 1.05);
  return g;
}

/* ------------------------------------------------------------------ */
/* Load                                                                */
/* ------------------------------------------------------------------ */

const gltfLoader = new GLTFLoader();
gltfLoader.setMeshoptDecoder(MeshoptDecoder);
const loadGLB = (url) => new Promise((resolve, reject) => gltfLoader.load(url, resolve, undefined, reject));

async function init() {
  const [headRes, armRes] = await Promise.allSettled([loadGLB(HEAD_GLB), loadGLB(ARM_GLB)]);

  let headRoot;
  if (headRes.status === "fulfilled") {
    headRoot = headRes.value.scene;
    prepareModel(headRoot, {
      glossy: true,
      tint: "#4a4238",
      rim: { color: C.copper, power: 4.5, strength: 0.34 },
    });
  } else {
    headRoot = buildFallbackHead();
  }
  normaliseHead(headRoot);

  let armTpl;
  if (armRes.status === "fulfilled") {
    armTpl = armRes.value.scene;
    prepareModel(armTpl, {
      glossy: false,
      tint: "#241f19",
      rim: { color: C.copper, power: 2.6, strength: 1.05 },
    });
  } else {
    armTpl = buildFallbackArm();
  }

  mountHead(headRoot, headRes.status === "fulfilled");
  mountArms(armTpl);

  measureModel();
  if (!layout()) return;
  ready = true;

  if (motionOff()) {
    staticPose();
  } else {
    intro = 0;
    robot.scale.setScalar(0.001);
    syncFlightMode(true);
    start();
  }
}

/* ------------------------------------------------------------------ */
/* Poses and loop                                                      */
/* ------------------------------------------------------------------ */

let webglShown = false;
function render() {
  renderer.render(scene, camera);
  if (!webglShown) {
    webglShown = true;
    host.classList.add("is-webgl-ready");
  }
}

/* Flat decals tangent to a sphere go edge-on as the head turns, so at yaw
   the far eye collapsed to a sliver while the near one still read fine and
   the pair looked unrelated. Blending each eye part-way toward facing the
   camera keeps both legible without detaching them from the face. */
const EYE_BILLBOARD = 0.55;
const _camLocal = new THREE.Vector3();
const _eyeDir = new THREE.Vector3();
const _qBill = new THREE.Quaternion();
const _Z = new THREE.Vector3(0, 0, 1);

function orientEyes() {
  head.updateMatrixWorld(true);
  _camLocal.copy(camera.position);
  head.worldToLocal(_camLocal);
  for (const eye of eyes) {
    _eyeDir.copy(_camLocal).sub(eye.group.position).normalize();
    _qBill.setFromUnitVectors(_Z, _eyeDir);
    eye.group.quaternion.copy(eye.qSurface).slerp(_qBill, EYE_BILLBOARD);
  }
}

function staticPose() {
  intro = 1;
  blinkT = -1;
  look.x = look.y = 0;
  target.x = target.y = 0;
  glance.until = -1;
  robot.scale.setScalar(1);
  robot.position.y = 0;
  robot.rotation.set(0, 0, 0);
  /* A small fixed turn toward the hero copy reads as attention rather
     than a dead-front mannequin, and it never moves. */
  head.rotation.set(-0.05, -0.14, 0.02);
  body.rotation.set(0, -0.07, 0);
  orientEyes();
  for (const { wrap, def } of arms) {
    wrap.position.set(def.x, def.y, def.z);
    wrap.rotation.set(0, 0, def.rz);
  }
  for (const eye of eyes) {
    eye.group.scale.y = 1;
    eye.pupilWrap.position.set(0, 0, 0);
  }
  for (const g of antennaGlows) g.material.opacity = 0.85;
  render();
}

const clock = new THREE.Clock();
let lastMobileRenderT = 0;

function tick() {
  rafId = requestAnimationFrame(tick);
  const isMobile = window.innerWidth <= 768 || window.matchMedia("(pointer: coarse)").matches;
  const now = performance.now();
  if (isMobile && now - lastMobileRenderT < 32) {
    /* 30 FPS mobile battery governor: halves GPU draw calls on mobile */
    return;
  }
  lastMobileRenderT = now;

  const rawDt = clock.getDelta();
  const dt = Math.min(rawDt, 0.05);
  const flightDt = Math.min(rawDt, 0.09);
  elapsed += dt;
  const t = elapsed;

  let dockBias = 0;
  let workBias = 0;
  let contactBias = 0;
  let expBias = 0;
  let scrollTiltX = 0;
  let armSwayBoost = 1;
  let hopBank = 0;
  let hopPitch = 0;
  let hopGlow = 0;
  let landY = 0;
  let landSquashX = 1;
  let landSquashY = 1;

  if (flight.active) {
    const prevP = flight.p;
    const follow = 1 - Math.exp(-8.5 * flightDt);
    flight.p += (flight.targetP - flight.p) * follow;
    if (Math.abs(flight.targetP - flight.p) < 0.0004) {
      flight.p = flight.targetP;
    }
    const rawVel = flightDt > 1e-4 ? (flight.p - prevP) / flightDt : 0;
    flight.vel += (rawVel - flight.vel) * (1 - Math.exp(-12 * flightDt));

    const prevCP = contactFlight.p;
    const cFollow = 1 - Math.exp(-8.2 * flightDt);
    contactFlight.p += (contactFlight.targetP - contactFlight.p) * cFollow;
    if (Math.abs(contactFlight.targetP - contactFlight.p) < 0.0004) {
      contactFlight.p = contactFlight.targetP;
    }
    const rawCVel = flightDt > 1e-4 ? (contactFlight.p - prevCP) / flightDt : 0;
    contactFlight.vel += (rawCVel - contactFlight.vel) * (1 - Math.exp(-12 * flightDt));

    const prevEP = expFlight.p;
    const eFollow = 1 - Math.exp(-9.2 * flightDt);
    expFlight.p += (expFlight.targetP - expFlight.p) * eFollow;
    if (Math.abs(expFlight.targetP - expFlight.p) < 0.0004) {
      expFlight.p = expFlight.targetP;
    }
    const rawEVel = flightDt > 1e-4 ? (expFlight.p - prevEP) / flightDt : 0;
    expFlight.vel += (rawEVel - expFlight.vel) * (1 - Math.exp(-12 * flightDt));

    const prevWP = workFlight.p;
    const wFollow = 1 - Math.exp(-9.4 * flightDt);
    workFlight.p += (workFlight.targetP - workFlight.p) * wFollow;
    if (Math.abs(workFlight.targetP - workFlight.p) < 0.0004) {
      workFlight.p = workFlight.targetP;
    }
    const rawWVel = flightDt > 1e-4 ? (workFlight.p - prevWP) / flightDt : 0;
    workFlight.vel += (rawWVel - workFlight.vel) * (1 - Math.exp(-12 * flightDt));

    workFlight.targetPosP = clamp(registry.workMascotState?.progress ?? 0, 0, 1);
    if (prevWP <= 0.002 && workFlight.targetP > 0) {
      workFlight.posP = workFlight.targetPosP;
      workFlight.posVel = 0;
    } else {
      const prevPosP = workFlight.posP;
      const posFollow = 1 - Math.exp(-14 * flightDt);
      workFlight.posP += (workFlight.targetPosP - workFlight.posP) * posFollow;
      if (Math.abs(workFlight.targetPosP - workFlight.posP) < 0.0004) {
        workFlight.posP = workFlight.targetPosP;
      }
      const rawPosVel = flightDt > 1e-4 ? (workFlight.posP - prevPosP) / flightDt : 0;
      workFlight.posVel += (rawPosVel - workFlight.posVel) * (1 - Math.exp(-12 * flightDt));
    }

    scrollState.vel += (scrollState.targetVel - scrollState.vel) * (1 - Math.exp(-10 * dt));
    scrollState.targetVel *= Math.exp(-8 * dt);
    if (Math.abs(scrollState.vel) < 1) scrollState.vel = 0;

    const heroDock = smoothstep(flight.p);
    workBias = smoothstep(workFlight.p);
    contactBias = smoothstep(contactFlight.p);
    expBias = smoothstep(expFlight.p);
    dockBias = heroDock * (1 - workBias) * (1 - contactBias) * (1 - expBias);

    if (expFlight.p > 0.0005 || expFlight.targetP > 0.0005) {
      resolveExpPanelTarget(false);
    }

    if (expPerch.hopT < 1) {
      expPerch.hopT = Math.min(1, expPerch.hopT + flightDt / Math.max(expPerch.hopDur, 0.25));
      const th = expPerch.hopT;
      const arcSin = Math.sin(th * Math.PI);
      hopBank = -expPerch.hopDir * Math.sin(th * Math.PI * 1.15) * 0.14 * expBias;
      hopPitch = -arcSin * 0.08 * expBias;
      hopGlow = arcSin * 0.28 * expBias;
      if (th >= 1) {
        expPerch.landBounceT = 0;
      }
    }
    if (expPerch.landBounceT >= 0) {
      expPerch.landBounceT += dt / 0.24;
      if (expPerch.landBounceT >= 1) {
        expPerch.landBounceT = -1;
      } else {
        const lb = expPerch.landBounceT;
        const damp = Math.exp(-lb * 5.2);
        const wave = Math.sin(lb * Math.PI * 2.2);
        landY = -wave * 0.07 * damp * expBias;
        landSquashY = 1 - wave * 0.042 * damp * expBias;
        landSquashX = 1 + wave * 0.026 * damp * expBias;
      }
    }

    const desiredBuoyY = clamp(-scrollState.vel * 0.0045, -10, 6) * dockBias;
    scrollState.buoyY += (desiredBuoyY - scrollState.buoyY) * (1 - Math.exp(-9 * dt));

    const scrollNorm = clamp(scrollState.vel / 2400, -1, 1);
    scrollTiltX = -scrollNorm * 0.075 * dockBias;
    armSwayBoost = 1 + Math.abs(scrollNorm) * 0.35 * dockBias;

    const desiredBank = clamp(
      flight.vel * 0.09 - contactFlight.vel * 0.08 + expFlight.vel * 0.06 + workFlight.vel * 0.06 - workFlight.posVel * 0.14 * workBias,
      -0.11,
      0.11
    );
    flight.bank += (desiredBank - flight.bank) * (1 - Math.exp(-10 * dt));

    applyFlightTransform(false);

    if (
      lastPointer.has &&
      t - lastMoveT <= 3.5 &&
      (Math.abs(flight.vel) > 0.01 ||
        Math.abs(workFlight.vel) > 0.01 ||
        Math.abs(workFlight.posVel) > 0.01 ||
        Math.abs(contactFlight.vel) > 0.01 ||
        Math.abs(expFlight.vel) > 0.01 ||
        expPerch.hopT < 1)
    ) {
      pointerToTarget(lastPointer.x, lastPointer.y, target);
    }
  } else {
    flight.bank = 0;
    flight.vel = 0;
    workFlight.vel = 0;
    workFlight.posVel = 0;
    contactFlight.vel = 0;
    expFlight.vel = 0;
    scrollState.vel = 0;
    scrollState.targetVel = 0;
    scrollState.buoyY = 0;
  }

  let cheerY = 0;
  let cheerTilt = 0;
  let cheerGlow = 0;
  if (cheerStart >= 0) {
    const cp = (t - cheerStart) / cheerDur;
    if (cp >= 1) {
      cheerStart = -1;
    } else {
      const env = 1 - cp;
      cheerY = Math.abs(Math.sin(cp * Math.PI * 2)) * env * 0.16;
      cheerTilt = Math.sin(cp * Math.PI * 4) * env * 0.11;
      cheerGlow = Math.sin(cp * Math.PI) * 0.25;
    }
  }

  const desiredSectionTilt = currentSection === "console" ? 0.055 : currentSection === "about" ? -0.035 : 0;
  sectionTiltZ += (desiredSectionTilt - sectionTiltZ) * (1 - Math.exp(-6 * dt));

  if (isMobile) {
    /* Autonomous gentle idle movement on mobile: no cursor/touch tracking */
    target.x = Math.sin(t * 0.45) * 0.32;
    target.y = Math.sin(t * 0.31 + 1.2) * 0.16;
  } else if (t - lastMoveT > 3.5 && t > glance.until) {
    const idleXBias =
      dockBias * 0.28 - contactBias * 0.24 + clamp(workFlight.posVel * 0.35, -0.35, 0.35) * workBias;
    const idleYBias = dockBias * -0.16 - contactBias * 0.06 + expBias * 0.1 + workBias * 0.14;
    target.x =
      idleXBias +
      Math.sin(t * 0.45) * (0.45 - (dockBias + contactBias + expBias * 0.5 + workBias * 0.5) * 0.1);
    target.y =
      idleYBias +
      Math.sin(t * 0.31 + 1.2) * (0.2 - (dockBias + contactBias + expBias * 0.5 + workBias * 0.5) * 0.03);
  }

  const s = 1 - Math.pow(0.0025, dt);
  const gx = t < glance.until ? glance.x : target.x;
  const gy = t < glance.until ? glance.y : target.y;
  look.x += (gx - look.x) * s;
  look.y += (gy - look.y) * s;

  if (intro >= 0 && intro < 1) intro = Math.min(1, intro + dt * 1.4);
  if (intro >= 0) {
    const k = intro;
    const introScale = Math.max(1 + 2.4 * Math.pow(k - 1, 3) + 1.4 * Math.pow(k - 1, 2), 0.001);
    robot.scale.set(introScale * landSquashX, introScale * landSquashY, introScale * landSquashX);
  }

  robot.rotation.z = flight.bank + hopBank;
  robot.rotation.x =
    Math.abs(
      flight.vel +
        workFlight.vel * 0.6 +
        Math.abs(workFlight.posVel) * 0.5 * workBias +
        contactFlight.vel +
        expFlight.vel * 0.55
    ) *
      0.035 +
    hopPitch;

  const flightLift = clamp(
    (flight.vel +
      Math.abs(workFlight.vel) * 0.5 +
      Math.abs(workFlight.posVel) * 0.25 * workBias +
      Math.abs(contactFlight.vel) * 0.6 +
      Math.abs(expFlight.vel) * 0.45) *
      0.035,
    -0.04,
    0.07
  );
  const bobAmp = 0.09 * (1 - 0.35 * expBias);
  robot.position.y = Math.sin(t * 1.6) * bobAmp + flightLift + cheerY + landY;
  const bob = robot.position.y;

  head.rotation.y = look.x * 0.5;
  head.rotation.x = look.y * 0.42;
  head.rotation.z = -look.x * 0.06 + Math.sin(t * 1.1) * 0.015 + sectionTiltZ + cheerTilt;

  body.rotation.y = look.x * 0.28 + dockBias * 0.16 - contactBias * 0.14;
  body.rotation.x = look.y * 0.12 + scrollTiltX;

  orientEyes();

  for (const { wrap, def } of arms) {
    const w = Math.sin(t * 2.0 + def.phase) * armSwayBoost;
    const sign = Math.sign(def.x);
    wrap.position.y = def.y + w * 0.13 - bob * 0.35 + cheerY * 0.4;
    wrap.position.x = def.x + sign * look.x * -0.04;
    wrap.rotation.z = def.rz + w * 0.12 * sign;
    wrap.rotation.x = Math.sin(t * 1.3 + def.phase) * 0.08 + scrollTiltX * 0.5;
  }

  const px = clamp(look.x * 0.075, -0.07, 0.07);
  const py = clamp(-look.y * 0.06, -0.06, 0.06);
  for (const eye of eyes) eye.pupilWrap.position.set(px, py, 0);

  if (blinkT < 0 && t >= nextBlink) {
    blinkT = 0;
    nextBlink = t + 2.5 + Math.random() * 3.5;
  }
  if (blinkT >= 0) {
    blinkT += dt;
    const p = blinkT / 0.32;
    if (p >= 1) {
      blinkT = -1;
      for (const e of eyes) e.group.scale.y = 1;
    } else {
      const sc = 0.08 + 0.92 * Math.abs(Math.cos(Math.PI * p));
      for (const e of eyes) e.group.scale.y = sc;
    }
  }

  const ag = Math.min(1, 0.75 * (0.85 + Math.sin(t * 1.8) * 0.15) + 0.2 + cheerGlow + hopGlow);
  const antScale = 0.62 + Math.sin(t * 2.2) * 0.06 + (cheerGlow + hopGlow) * 0.25;
  for (const g of antennaGlows) {
    g.material.opacity = ag;
    g.scale.set(antScale, antScale, 1);
  }
  haze.material.opacity = 0.18 + Math.sin(t * 1.2) * 0.05;

  render();
}

function start() {
  if (running || !ready) return;
  running = true;
  clock.getDelta();
  rafId = requestAnimationFrame(tick);
}

function stop() {
  if (!running) return;
  running = false;
  cancelAnimationFrame(rafId);
}

function sync() {
  if (!ready) return;
  syncFlightMode(motionOff() ? false : !flight.active);
  if (motionOff() || document.hidden || (!flight.active && !heroVisible) || !layout()) {
    stop();
    if (motionOff() && W && H) staticPose();
    return;
  }
  start();
}

function refreshFlight() {
  if (!ready || !flight.active) return;
  measureFlightMetrics();
  flight.targetP = computeScrollProgress();
  workFlight.targetP = computeWorkTarget();
  workFlight.targetPosP = clamp(registry.workMascotState?.progress ?? 0, 0, 1);
  contactFlight.targetP = computeContactTarget();
  expFlight.targetP = computeExpTarget();
  resolveExpPanelTarget(expPerch.hopT >= 1);
  applyFlightTransform(true);
}

/* ------------------------------------------------------------------ */
/* Lifecycle                                                           */
/* ------------------------------------------------------------------ */

function onScroll() {
  const now = performance.now();
  const y = window.scrollY;
  const dtS = Math.max((now - scrollState.lastT) / 1000, 0.008);
  if (now - scrollState.lastT < 250) {
    scrollState.targetVel = clamp((y - scrollState.lastY) / dtS, -3600, 3600);
  }
  scrollState.lastY = y;
  scrollState.lastT = now;

  if (!hasScrolledFlight && y > 2) {
    hasScrolledFlight = true;
    syncFlightMode(true);
    sync();
  }
  if (!flight.active) return;
  if (!running && !motionOff() && !document.hidden) start();
  flight.targetP = computeScrollProgress();
  workFlight.targetP = computeWorkTarget();
  workFlight.targetPosP = clamp(registry.workMascotState?.progress ?? 0, 0, 1);
  contactFlight.targetP = computeContactTarget();
  expFlight.targetP = computeExpTarget();
  if (expFlight.p > 0.0005 || expFlight.targetP > 0.0005) {
    resolveExpPanelTarget(false);
  }
  if (
    workFlight.p > 0.0005 ||
    workFlight.targetP > 0.0005 ||
    contactFlight.p > 0.0005 ||
    contactFlight.targetP > 0.0005 ||
    expFlight.p > 0.0005 ||
    expFlight.targetP > 0.0005
  ) {
    applyFlightTransform(false);
  }
  if (lastPointer.has && elapsed - lastMoveT <= 3.5) {
    pointerToTarget(lastPointer.x, lastPointer.y, target);
  }
}

window.addEventListener("scroll", onScroll, { passive: true });
window.addEventListener("resize", refreshFlight, { passive: true });
document.fonts?.ready.then(refreshFlight);

new IntersectionObserver(
  (entries) => {
    heroVisible = entries[0].isIntersecting;
    sync();
  },
  { threshold: 0 }
).observe(hero);

new ResizeObserver(() => {
  if (!ready) return;
  if (!layout()) {
    stop();
    return;
  }
  refreshFlight();
  if (motionOff()) {
    stop();
    staticPose();
    return;
  }
  sync();
}).observe(host);

if (heroSide) {
  new ResizeObserver(refreshFlight).observe(heroSide);
}
if (mainEl) {
  new ResizeObserver(refreshFlight).observe(mainEl);
}
if (connectCard) {
  new ResizeObserver(refreshFlight).observe(connectCard);
}
new ResizeObserver(refreshFlight).observe(root);

document.addEventListener("visibilitychange", sync);
reduceQuery.addEventListener("change", sync);
new MutationObserver(sync).observe(root, { attributes: true, attributeFilter: ["data-motion"] });

canvas.addEventListener("webglcontextlost", (event) => {
  event.preventDefault();
  stop();
  ready = false;
  syncFlightMode(false);
  host.classList.add("mascot--failed");
});

/* The robot looks at the command palette (or a custom screen point) on demand. */
window.__mascotGlance = (targetX, targetY) => {
  if (!ready || motionOff()) return;
  if (typeof targetX === "number" && typeof targetY === "number") {
    pointerToTarget(targetX, targetY, glance);
  } else {
    const dlg = document.getElementById("palette");
    if (dlg) {
      const r = dlg.getBoundingClientRect();
      if (r.width) {
        pointerToTarget(r.left + r.width / 2, r.top + r.height / 2, glance);
      }
    }
  }
  glance.until = elapsed + 1.8;
  if (!running) start();
};

window.__mascotSection = (id) => {
  currentSection = id || "top";
};

window.__mascotCheer = (kind = "happy") => {
  if (!ready || motionOff()) return;
  cheerDur = kind === "celebrate" ? 0.72 : 0.52;
  cheerStart = elapsed;
  if (!running) start();
};

registry.onExpMascotFrame = () => {
  if (!ready || !flight.active) return;
  expFlight.targetP = computeExpTarget();
  if (motionOff()) {
    expFlight.p = expFlight.targetP;
    resolveExpPanelTarget(true);
    applyFlightTransform(true);
    return;
  }
  if (expFlight.p > 0.0005 || expFlight.targetP > 0.0005) {
    resolveExpPanelTarget(false);
    applyFlightTransform(false);
  }
};

registry.onWorkMascotFrame = () => {
  if (!ready || !flight.active) return;
  workFlight.targetP = computeWorkTarget();
  workFlight.targetPosP = clamp(registry.workMascotState?.progress ?? 0, 0, 1);
  if (workFlight.targetP > 0 && workFlight.p <= 0.002) {
    workFlight.posP = workFlight.targetPosP;
    workFlight.posVel = 0;
  }
  if (motionOff()) {
    workFlight.p = workFlight.targetP;
    workFlight.posP = workFlight.targetPosP;
    applyFlightTransform(true);
    return;
  }
  if (!running && !document.hidden && (workFlight.p > 0.0005 || workFlight.targetP > 0.0005)) {
    start();
  }
  if (workFlight.p > 0.0005 || workFlight.targetP > 0.0005) {
    applyFlightTransform(false);
  }
};

smallScreen.addEventListener("change", () => {
  if (!ready) return;
  syncFlightMode(true);
  layout();
  sync();
});

init().catch((error) => {
  ready = false;
  stop();
  host.classList.add("mascot--failed");
  console.warn("mascot: could not start", error);
});
